namespace RonSijm.FluidHumidifier.Factories.GameLift;

public class ContainerFleetFactory(string resourceName = null, Action<Humidifier.GameLift.ContainerFleet> factoryAction = null) : ResourceFactory<Humidifier.GameLift.ContainerFleet>(resourceName)
{

    internal List<InnerContainerFleetScalingPolicyFactory> ScalingPoliciesFactories { get; set; } = [];

    internal List<InnerContainerFleetLocationConfigurationFactory> LocationsFactories { get; set; } = [];

    internal List<InnerContainerFleetIpPermissionFactory> InstanceInboundPermissionsFactories { get; set; } = [];

    internal InnerContainerFleetGameSessionCreationLimitPolicyFactory GameSessionCreationLimitPolicyFactory { get; set; }

    internal InnerContainerFleetLogConfigurationFactory LogConfigurationFactory { get; set; }

    internal InnerContainerFleetConnectionPortRangeFactory InstanceConnectionPortRangeFactory { get; set; }

    internal InnerContainerFleetDeploymentConfigurationFactory DeploymentConfigurationFactory { get; set; }

    protected override Humidifier.GameLift.ContainerFleet Create()
    {
        var containerFleetResult = CreateContainerFleet();
        factoryAction?.Invoke(containerFleetResult);

        return containerFleetResult;
    }

    private Humidifier.GameLift.ContainerFleet CreateContainerFleet()
    {
        var containerFleetResult = new Humidifier.GameLift.ContainerFleet
        {
            GivenName = InputResourceName,
        };

        return containerFleetResult;
    }
    public override void CreateChildren(Humidifier.GameLift.ContainerFleet result)
    {
        base.CreateChildren(result);

        result.ScalingPolicies = ScalingPoliciesFactories.Any() ? ScalingPoliciesFactories.Select(x => x.Build()).ToList() : null;
        result.Locations = LocationsFactories.Any() ? LocationsFactories.Select(x => x.Build()).ToList() : null;
        result.InstanceInboundPermissions = InstanceInboundPermissionsFactories.Any() ? InstanceInboundPermissionsFactories.Select(x => x.Build()).ToList() : null;
        result.GameSessionCreationLimitPolicy ??= GameSessionCreationLimitPolicyFactory?.Build();
        result.LogConfiguration ??= LogConfigurationFactory?.Build();
        result.InstanceConnectionPortRange ??= InstanceConnectionPortRangeFactory?.Build();
        result.DeploymentConfiguration ??= DeploymentConfigurationFactory?.Build();
    }

} // End Of Class

